@'
import assert from 'node:assert/strict';
import {readFileSync, readdirSync, existsSync} from 'node:fs';
import path from 'node:path';
import {loadPackageFromDirectory} from './packages/core/src/application/package-loader.ts';
import {validatePackage} from './packages/core/src/application/validate-package.ts';
import {NodeFileSystem} from './packages/node/src/file-system.ts';
import {ClaudeCodeAdapter} from './packages/adapter-claude/src/index.ts';
import {CodexAdapter} from './packages/adapter-codex/src/index.ts';
const root = 'skills/distributed-systems-testing';
const loaded = await loadPackageFromDirectory(new NodeFileSystem(), root, {strict: true});
const report = validatePackage(loaded.pkg, {
  directoryName: 'distributed-systems-testing',
  adapters: [new ClaudeCodeAdapter(), new CodexAdapter()]
});
const issues = [...loaded.issues, ...report.issues];
assert.equal(issues.length, 0, JSON.stringify(issues));
const entry = readFileSync(path.join(root, 'SKILL.md'), 'utf8');
const refFiles = readdirSync(path.join(root, 'references'));
for (const file of refFiles) assert.ok(entry.includes('references/' + file), 'Unrouted reference ' + file);
const files = ['SKILL.md', ...refFiles.map(f => 'references/' + f)];
let linksChecked = 0;
for (const file of files) {
  const text = readFileSync(path.join(root, file), 'utf8');
  for (const match of text.matchAll(/\]\(([^)]+)\)/g)) {
    const href = match[1];
    if (/^[a-z]+:\/\//i.test(href)) continue;
    const [target, anchor] = href.split('#');
    const resolved = target ? path.resolve(root, path.dirname(file), target) : path.resolve(root, file);
    assert.ok(existsSync(resolved), file + ': ' + href);
    if (anchor) {
      const targetText = readFileSync(resolved, 'utf8');
      const anchors = [...targetText.matchAll(/^#+ (.+)$/gm)]
        .map(m => m[1].toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-'));
      assert.ok(anchors.includes(anchor), file + ': absent anchor ' + href);
    }
    linksChecked++;
  }
}
assert.ok(entry.includes('references/fault-injection.md#death-mid-flight'));
assert.ok(readFileSync(path.join(root, 'references/fault-injection.md'), 'utf8').includes('## Death mid-flight'));
console.log(JSON.stringify({name: 'distributed-systems-testing', version: loaded.pkg.manifest.version, issues, referenceFilesRouted: refFiles.length, localMarkdownLinksChecked: linksChecked, newBacktickAnchor: 'present'}, null, 2));

'@ | node --input-type=module -

